import{_ as a,r as c,o,b as n,a as s,d as i,w as d,y as l,e as p}from"./index-565feec3.js";const v={},r={class:"memory-page"},_={class:"content-wrapper"},x={class:"header-section"};function m(h,t){const e=c("router-link");return o(),n("div",r,[s("div",_,[s("div",x,[i(e,{to:"/game",class:"back-button"},{default:d(()=>[...t[0]||(t[0]=[p(" ← 返回 ",-1)])]),_:1}),t[1]||(t[1]=s("h1",{class:"title"},"记忆衰减曲线",-1))]),t[2]||(t[2]=l('<div class="card" data-v-30675365><section class="section" data-v-30675365><h2 class="section-title" data-v-30675365>一、记忆衰减曲线概述</h2><p class="section-text" data-v-30675365> 记忆衰减曲线是基于艾宾浩斯遗忘规律与指数衰减模型构建的数学描述，用于量化呈现人类记忆内容随时间推移而逐步丢失的动态过程。它以时间为横轴、记忆保留率为纵轴，直观反映信息从识记到遗忘的速率变化，是认知心理学中解释记忆规律、指导高效学习的核心依据。 </p></section><section class="section" data-v-30675365><h2 class="section-title" data-v-30675365>二、科学原理与数学模型</h2><p class="section-text" data-v-30675365> 记忆的遗忘过程并非匀速，而是先快后慢，符合指数衰减函数：保留率 = 初始正确率 × e^(-t/k) </p><p class="section-text" data-v-30675365> e：自然常数（约 2.718） </p><p class="section-text" data-v-30675365> k：遗忘速率参数 </p><p class="section-text" data-v-30675365> t：时间间隔 </p><p class="section-text" data-v-30675365> 该模型可精准拟合个体在不同延时时下的记忆表现，生成专属记忆衰减曲线。 </p></section><section class="section" data-v-30675365><h2 class="section-title" data-v-30675365>三、本项目记忆衰减模块设计</h2><p class="section-text" data-v-30675365> 任务范式采用识记 — 延时 — 再认标准实验流程：先让被试学习词对信息，分别在0秒，20秒、1分钟、2分钟三个延时节点进行匹配测试，记录各时间点记忆正确率。 </p><p class="section-text" data-v-30675365> 数据采集记录每个延时节点的记忆保留率，作为曲线拟合的核心数据。 </p><p class="section-text" data-v-30675365> 可视化呈现基于实测数据绘制个性化指数衰减曲线，直观展示被试的记忆遗忘速度，帮助理解 “及时复习” 的科学依据，为学习策略优化提供量化参考。 </p><p class="section-text" data-v-30675365> 科普价值以游戏化方式还原经典记忆实验，破除 “记忆靠天赋” 的认知误区，让大学生直观理解记忆可量化、遗忘有规律，兼具科学性与教育意义。 </p></section><section class="section" data-v-30675365><h2 class="section-title" data-v-30675365>四、权威合规声明</h2><p class="section-text" data-v-30675365> 本记忆衰减曲线为心理建模科普工具，基于认知心理学经典范式设计，仅用于展示记忆规律与学习参考，不构成记忆力评估、智力测验或临床诊断；数据匿名采集，仅用于个人历史查看与科普研究。 </p></section></div>',1))])])}const f=a(v,[["render",m],["__scopeId","data-v-30675365"]]);export{f as default};
